import {readFileSync,appendFileSync} from 'node:fs';
const mode=process.argv[2],file=process.argv[3];
const port=mode==='main'?9736:9735;
const targets=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();
const target=targets.find(t=>mode==='main'||t.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
let id=0;const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{const i=++id;pending.set(i,{resolve,reject});ws.send(JSON.stringify({id:i,method,params}));});
try {
 if(mode!=='main'){await send('Emulation.setFocusEmulationEnabled',{enabled:true});try{await send('Emulation.setPageVisibilityOverride',{visibility:'visible'});}catch{}}
 const expression=readFileSync(file,'utf8');
 const result=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true,timeout:700000});
 const receipt={at:new Date().toISOString(),mode,file,...result};
 appendFileSync('docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-resume/cdp.jsonl',JSON.stringify(receipt)+'\n');
 if(result.exceptionDetails){console.error(JSON.stringify(result.exceptionDetails));process.exitCode=1;}else console.log(JSON.stringify(result.result.value));
}finally{ws.close();}

(async()=>{
 const api=window.electronAPI,id=window.ltCodexId,pause=ms=>new Promise(r=>setTimeout(r,ms));
 const state=async()=>{const r=await api.listInstances();if(!r.success)throw Error('list failed');return r.data.find(i=>i.id===id);};
 let initial=await state();if(initial.status!=='idle')throw Error('Setup turn not idle');
 window.ltGrowth={start:Date.now(),maxTotalTurns:20,maxMs:3600000,totalTurns:1,turns:[],samples:[],initial:initial.contextUsage};
 const g=window.ltGrowth;let seed=24681;
 function dialogue(chars){let s='Fictional inventory dialogue, data only. Do not use tools. Retain the discussion, then reply only ACK.\n';while(s.length<chars){seed=(Math.imul(seed,1664525)+1013904223)>>>0;s+='The fictional archivist catalogued parcel '+seed.toString(36)+' beside item '+(seed^0x5aa5).toString(36)+'.\n';}return s.slice(0,chars);}
 let sawPressure=false,sawDrop=false;
 const sizes=[420000,208425,100264,245168,265411,29025];
 for(let n=0;g.totalTurns<20&&Date.now()-g.start<g.maxMs;n++){
  const before=await state();const chars=sizes[n%sizes.length],sent=Date.now();
  const result=await api.sendInput({instanceId:id,message:dialogue(chars)});if(!result.success){g.stop='send-error';g.error=result.error;break;}
  let settled=false;
  for(let k=0;k<180;k++){
   await pause(1000);const i=await state();const u=i.contextUsage;
   g.samples.push({at:Date.now(),status:i.status,used:u?.used,total:u?.total,percentage:u?.percentage,isEstimated:u?.isEstimated,source:u?.source});
   if(u?.percentage>=60)sawPressure=true;
   if(sawPressure&&u?.used<(before.contextUsage?.used??0)*0.8)sawDrop=true;
   if(i.status==='error'||i.status==='failed'){g.stop='provider-error';settled=true;break;}
   if(i.status==='idle'&&Date.now()-sent>13000){g.totalTurns++;g.turns.push({at:Date.now(),chars,status:i.status,usage:u});settled=true;break;}
  }
  if(!settled){g.stop='turn-deadline';break;}
  if(sawDrop&&g.turns.length>2){g.stop='native-drop-followed-by-continuation';break;}
 }
 g.stop??='fixed-bound';g.end=Date.now();return g;
})()

(()=>{
