 const create=runtime.createAdapter;
 globalThis.ltReviewShapes=[];globalThis.ltReviewerAdapters=[];
 runtime.createAdapter=function(request){
  const adapter=create.call(this,request);
  if(request.cliType==='claude'){
   const shapes={at:Date.now(),readOnly:request.options?.readOnlyReview,model:request.options?.model,maxTurns:request.options?.maxTurns,events:[]};
   ltReviewShapes.push(shapes);ltReviewerAdapters.push(adapter);
   const spawn=adapter.spawnWithInlineArgCleanup;
   adapter.spawnWithInlineArgCleanup=function(args){
    const child=spawn.call(this,args);shapes.pid=child.pid;shapes.argFlags=args.filter(s=>s.startsWith('--'));
    let buf='';child.stdout?.on('data',chunk=>{buf+=String(chunk);let n;while((n=buf.indexOf('\n'))>=0){const line=buf.slice(0,n);buf=buf.slice(n+1);try{const p=JSON.parse(line);shapes.events.push({at:Date.now(),type:p.type,subtype:p.subtype,stopReason:p.stop_reason,isError:p.is_error,hasStructured:!!p.structured_output,toolNames:Array.isArray(p.message?.content)?p.message.content.filter(b=>b.type==='tool_use').map(b=>b.name):undefined});}catch{}}});
    child.on('close',code=>shapes.events.push({at:Date.now(),type:'process-close',code}));return child;
   };
  }
  return adapter;
 };
 globalThis.ltRestoreReviewer=()=>{runtime.createAdapter=create;};
 return {capabilities:a.getContextCapabilities(),thread:a.appServerRuntime.binding.threadId,usage:ltManager.getAllInstances()[0].contextUsage};
})()

